dashboard.definition:
{
    "title": "Operational Intelligence",
    "description": "Coordinate telemetry readiness, path health, routing instability, and AI Defense signals.",
    "inputs": {
        "input_time_range": {
            "options": {
                "defaultValue": "-24h,now,1h",
                "showAdvanced": true,
                "selections": [
                    {
                        "value": "-4h,now,30m",
                        "label": "4h"
                    },
                    {
                        "value": "-24h,now,1h",
                        "label": "24h"
                    },
                    {
                        "value": "-48h,now,2h",
                        "label": "48h"
                    },
                    {
                        "value": "-7d@d,now,1d",
                        "label": "7d"
                    },
                    {
                        "value": "-30d@d,now,1d",
                        "label": "30d"
                    }
                ],
                "token": "time_tok"
            },
            "title": "Time range",
            "type": "input.simpleTimePicker"
        }
    },
    "defaults": {
        "visualizations": {
            "global": {
                "showLastUpdated": true,
                "showProgressBar": true
            }
        }
    },
    "visualizations": {
        "viz_header_bg": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#1c2738",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 10
            }
        },
        "viz_header_icon": {
            "type": "splunk.image",
            "title": "Operational Intelligence",
            "options": {
                "preserveAspectRatio": true,
                "src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/agentic-ops.svg"
            }
        },
        "viz_header": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "markdown": "# Operational Intelligence\nCoordinate telemetry readiness, path health, routing instability, and AI Defense signals\\."
            }
        },
        "viz_card_01_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_01_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**ThousandEyes Feed Freshness**"
            }
        },
        "viz_card_01_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Monitoring  •  ThousandEyes"
            }
        },
        "viz_card_01_description": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#a6adb6",
                "fontSize": "custom",
                "customFontSize": 15,
                "markdown": "Staleness monitor for the ThousandEyes OTel metric stream\\. Detects feed death within 30 minutes \\- the typical symptom of an OAuth2 token expiry, endpoint URL change after a TE platform upgrade, or HEC token rotation\\."
            }
        },
        "viz_card_01_singlevalue": {
            "type": "splunk.singlevalue",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "majorColor": "#ecf0f5",
                "majorFontSize": 44,
                "majorValue": "> sparklineValues | lastPoint()",
                "shouldAbbreviateMajorValue": true,
                "sparklineDisplay": "off",
                "trendDisplay": "percent",
                "shouldAbbreviateTrendValue": true,
                "showTrendIndicator": true,
                "sparklineValues": "> primary | seriesByName(\"age_minutes\")",
                "trendColor": "> trendValue | rangeValue(trendColorEditorConfig)",
                "trendFontSize": 28,
                "trendValue": "> sparklineValues | delta(-2)"
            },
            "context": {
                "trendColorEditorConfig": [
                    {
                        "value": "#4cbf7f",
                        "to": -0.000001
                    },
                    {
                        "value": "#a6adb6",
                        "from": -0.000001,
                        "to": 0.000001
                    },
                    {
                        "value": "#f7782f",
                        "from": 0.000001
                    }
                ]
            }
        },
        "viz_card_01_trend": {
            "type": "splunk.area",
            "title": "",
            "dataSources": {
                "primary": "ds_story_01"
            },
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "off",
                "seriesColors": [
                    "#649ef5",
                    "#4cbf7f",
                    "#f7782f",
                    "#fa5762"
                ],
                "dataValuesDisplay": "minmax",
                "lineWidth": 3,
                "markerDisplay": "outlined",
                "nullValueDisplay": "connect",
                "showYMajorGridLines": true,
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "x": "> primary | seriesByName(\"last_seen\")",
                "y": "> primary | seriesByName(\"age_minutes\")"
            }
        },
        "viz_card_01_drilldown_trigger": {
            "type": "splunk.rectangle",
            "eventHandlers": [
                {
                    "type": "drilldown.customUrl",
                    "options": {
                        "url": "/drilldown?origin=ThousandEyes%20Feed%20Freshness&target=Feed%20Monitor%20-%20ALL%20Feeds%20-%20Consolidated%20Health%20Matrix"
                    }
                }
            ],
            "options": {
                "fillColor": "transparent",
                "strokeColor": "transparent"
            },
            "context": {},
            "containerOptions": {},
            "showProgressBar": false,
            "showLastUpdated": false
        },
        "viz_card_02_background": {
            "type": "splunk.rectangle",
            "options": {
                "fillColor": "#131a23",
                "strokeColor": "rgba(100,158,245,0.28)",
                "rx": 12
            }
        },
        "viz_card_02_title": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#ecf0f5",
                "fontSize": "custom",
                "customFontSize": 20,
                "markdown": "**AI Defense Policy Outcomes**"
            }
        },
        "viz_card_02_metadata": {
            "type": "splunk.markdown",
            "title": "",
            "showLastUpdated": false,
            "showProgressBar": false,
            "options": {
                "backgroundColor": "transparent",
                "fontColor": "#649ef5",
                "fontSize": "custom",
                "customFontSize": 14,
                "markdown": "Security  •  GenAI Protection"
            }
